function EquipmentCultivateAndReclaimVo:GetRecycleItems()
    if self.recycleItems == nil then
        self.recycleItems = {}
        local strIdList = self:ParseStrings(self.recycleItemStr)
        local strNumList = self:ParseStrings(self.recycleItemNumStr)
        local minNum = math.min(#strIdList, #strNumList)

        for i = 1, minNum, 1 do
            local idList = self:ParseStrings(strIdList[i], "|")
            local numList= self:ParseStrings(strNumList[i], "|")
            local minNum2 = math.min(#idList, #numList)

            -- self.recycleItems[i] = self.recycleItems[i] or {}
            local t = {}
            for j = 1, minNum2, 1 do
                table.insert(t, {goodsId = checkNumber(idList[j]), num = checkNumber(numList[j]) })
            end
            table.insert(self.recycleItems, t)
            -- table.insert(self.recycleItems, self:ParseStrings(str))
            
        end
        
    end
    return self.recycleItems
